<?php
require_once dirname(__DIR__,2).'/lib/bootstrap.php';require_method('POST');require_csrf();$user=require_permission('SOLICITUD_APROBAR');$in=json_input();$id=(int)($in['solicitud_id']??0);$status=strtoupper(trim((string)($in['estatus']??'')));$comment=trim((string)($in['comentario']??''));if($id<=0||!in_array($status,['AUTORIZADA','RECHAZADA','CANCELADA'],true))json_response(['ok'=>false,'error'=>'Solicitud o estatus inválido'],400);$db=conectar();if(!$db)json_response(['ok'=>false,'error'=>'Sin conexión a base de datos'],503);$st=$db->prepare("SELECT * FROM presupuesto_solicitud WHERE solicitud_id=? FOR UPDATE");$st->bind_param('i',$id);$st->execute();$row=$st->get_result()->fetch_assoc();$st->close();if(!$row){$db->close();json_response(['ok'=>false,'error'=>'Solicitud no encontrada'],404);}if(!request_is_visible($db,$user,$row)&&!user_is_global($user)){$db->close();json_response(['ok'=>false,'error'=>'No tienes acceso a esta solicitud'],403);}if(in_array($row['estatus'],['PAGADA','CANCELADA'],true)){$db->close();json_response(['ok'=>false,'error'=>'La solicitud ya no puede modificarse'],409);}$uid=(int)$user['user_id'];$st=$db->prepare("UPDATE presupuesto_solicitud SET estatus=?,resuelto_por_usuario_id=?,resuelto_at=NOW(),comentario_resolucion=? WHERE solicitud_id=?");$st->bind_param('sisi',$status,$uid,$comment,$id);$st->execute();$st->close();audit_log($db,$uid,'SOLICITUD_'.$status,'SOLICITUD',$id,$comment,$row,['estatus'=>$status,'comentario'=>$comment]);$db->close();json_response(['ok'=>true]);
